from random import randint

def 주사위():
    return randint(1, 6)

def 점수판(이름들, 점수들):
    for 이름, 점수 in zip(이름들, 점수들):
        print(이름, "■" * 점수, 점수)

def 이긴사람(이름들, 점수들):
    높은 = max(점수들)
    if 점수들.count(높은) > 1:
        return "비김"
    return 이름들[점수들.index(높은)]
